Object.assign(window.MATH_STATEMENTS, {
"1994-aime-1": { s: String.raw`The increasing sequence $3,$ $15,$ $24,$ $48,$ $\ldots$ consists of those positive multiples of $3$ that are one less than a perfect square. What is the remainder when the $1994$th term of the sequence is divided by $1000?$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-10": { s: String.raw`In triangle $ABC,$ angle $C$ is a right angle and the altitude from $C$ meets $\overline{AB}$ at $D.$ The lengths of the sides of $\triangle ABC$ are integers, $BD=29^3,$ and $\cos B=\frac{m}{n},$ where $m$ and $n$ are relatively prime positive integers. Find $m+n.$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-11": { s: String.raw`Ninety-four bricks, each measuring $4''\times10''\times19'',$ are to be stacked one on top of another to form a tower $94$ bricks tall. Each brick can be oriented so it contributes $4'',$ $10'',$ or $19''$ to the total height of the tower. How many different tower heights can be achieved using all $94$ of the bricks?`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-12": { s: String.raw`A fenced, rectangular field measures $24$ meters by $52$ meters. An agricultural researcher has $1994$ meters of fence that can be used for internal fencing to partition the field into congruent, square test plots. The entire field must be partitioned, and the sides of the squares must be parallel to the edges of the field. What is the largest number of square test plots into which the field can be partitioned using all or some of the $1994$ meters of fence?`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-13": { s: String.raw`The equation$$x^{10}+(13x-1)^{10}=0$$has $10$ complex roots $r_1,$ $\overline{r_1},$ $r_2,$ $\overline{r_2},$ $r_3,$ $\overline{r_3},$ $r_4,$ $\overline{r_4},$ $r_5,$ $\overline{r_5},$ where the bar denotes complex conjugation. Find the value of$$\frac1{r_1\overline{r_1}}+\frac1{r_2\overline{r_2}}+\frac1{r_3\overline{r_3}} +\frac1{r_4\overline{r_4}}+\frac1{r_5\overline{r_5}}.$$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-14": { s: String.raw`A beam of light strikes $\overline{BC}$ at point $C$ with angle of incidence $\alpha=19.94^\circ$ and reflects with an equal angle of reflection as shown. The light beam continues its path, reflecting off line segments $\overline{AB}$ and $\overline{BC}$ according to the rule: angle of incidence equals angle of reflection. Given that $\beta=\frac{\alpha}{10}=1.994^\circ$ and $AB=BC,$ determine the number of times the light beam will bounce off the two line segments. Include the first reflection at $C$ in your count.

@@fig:aime/1994/14.svg@@`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-15": { s: String.raw`Given a point $P$ on a triangular piece of paper $ABC,$ consider the creases that are formed in the paper when $A,$ $B,$ and $C$ are folded onto $P.$ Let us call $P$ a fold point of $\triangle ABC$ if these creases, which number three unless $P$ is one of the vertices, do not intersect. Suppose that $AB=36,$ $AC=72,$ and $\angle B=90^\circ.$ Then the area of the set of all fold points of $\triangle ABC$ can be written in the form $q\pi-r\sqrt s,$ where $q,$ $r,$ and $s$ are positive integers and $s$ is not divisible by the square of any prime. What is $q+r+s?$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-2": { s: String.raw`A circle with diameter $\overline{PQ}$ of length $10$ is internally tangent at $P$ to a circle of radius $20.$ Square $ABCD$ is constructed with $A$ and $B$ on the larger circle, $\overline{CD}$ tangent at $Q$ to the smaller circle, and the smaller circle outside $ABCD.$ The length of $\overline{AB}$ can be written in the form $m+\sqrt n,$ where $m$ and $n$ are integers. Find $m+n.$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-3": { s: String.raw`The function $f$ has the property that, for each real number $x,$$$f(x)+f(x-1)=x^2.$$If $f(19)=94,$ what is the remainder when $f(94)$ is divided by $1000?$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-4": { s: String.raw`Find the positive integer $n$ for which$$\lfloor\log_2 1\rfloor+\lfloor\log_2 2\rfloor+\lfloor\log_2 3\rfloor +\cdots+\lfloor\log_2 n\rfloor=1994.$$(For real $x,$ $\lfloor x\rfloor$ is the greatest integer not exceeding $x.$)`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-5": { s: String.raw`Given a positive integer $n,$ let $p(n)$ be the product of the nonzero digits of $n.$ (If $n$ has only one digit, then $p(n)$ is equal to that digit.) Let$$S =p(1)+p(2)+p(3) +\cdots+p(999).$$What is the largest prime factor of $S?$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-6": { s: String.raw`The graphs of the equations$$\begin{aligned}y&=k, \\ y&=\sqrt3x+2k, \\ y&=-\sqrt3x+2k,\end{aligned}$$are drawn in the coordinate plane for $k=-10,$ $-9,$ $-8,$ $\ldots,$ $9,$ $10.$ These $63$ lines cut part of the plane into equilateral triangles of side $\frac{2}{\sqrt3}.$ How many such triangles are formed?`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-7": { s: String.raw`For certain ordered pairs $(a,b)$ of real numbers, the system of equations$$\begin{aligned}ax+by&=1, \\ x^2+y^2&=50\end{aligned}$$has at least one solution, and each solution is an ordered pair $(x,y)$ of integers. How many such ordered pairs $(a,b)$ are there?`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-8": { s: String.raw`The points $(0,0),$ $(a,11),$ and $(b,37)$ are the vertices of an equilateral triangle. Find the value of $ab.$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
"1994-aime-9": { s: String.raw`A solitaire game is played as follows. Six distinct pairs of matched tiles are placed in a bag. The player randomly draws tiles one at a time from the bag and retains them, except that matching tiles are put aside as soon as they appear in the player’s hand. The game ends if the player ever holds three tiles, no two of which match; otherwise the drawing continues until the bag is empty. The probability that the bag will be emptied is $\frac{p}{q},$ where $p$ and $q$ are relatively prime positive integers. Find $p+q.$`, u: "https://live.poshenloh.com/past-contests/aime/1994" },
});
